353	// An action node either keeps the legacy `message` behavior, names a business
354	// operation the caller supplies at run time, and/or declares a compensation
355	// operation that undoes its business effect. Both retry blocks are optional
356	// and, absent, mean exactly one attempt with no waiting.
357	function compileAction(node) {
358	  let name = null;
359	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
360	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
361	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
362	    }
363	    name = node.operation;
364	  }
365	
366	  let retry = { ...DEFAULT_RETRY };
367	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
368	    if (!name) {
369	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
370	    }
371	    retry = compileRetry(node.retry, `action node ${node.id}`);
372	  }
373	
374	  let compensation = null;
375	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
376	    if (!isUsableObject(node.compensation)) {
377	      throw new Error(`action node ${node.id}: compensation must be an object`);
378	    }
379	    if (!name) {
380	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
381	    }
382	    const config = node.compensation;
383	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
384	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
385	    }
386	    let compRetry = { ...DEFAULT_RETRY };
387	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
388	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
389	    }
390	    compensation = { name: config.operation, retry: compRetry };
391	  }
392	
393	  // A legacy message action (no operation) may carry a structured object or
394	  // array as its message, and the output it saves is snapshotted per run. A
395	  // value the structured clone algorithm cannot deliver — a bare function or
396	  // a function nested inside an object/array — is a definition error naming
397	  // the action and the reason, for every message action including actions on
398	  // untaken branches and entry-unreachable ones. An action that names an
399	  // operation ignores its message entirely, so an unused uncloneable message
400	  // is never rejected for it.
401	  //
402	  // A value that clones but whose clone retains shared memory is rejected for
403	  // the same reason the run input and operation return values are: cloning a
404	  // SharedArrayBuffer (or a typed array / DataView backed by one) "succeeds"
405	  // while the clone keeps sharing the underlying bytes, so the independent
406	  // output copy the action promises — including against the definition's own
407	  // message, which the engine clones again at execution time — could not be
408	  // guaranteed. The check therefore runs on the cloned value with the same
409	  // clone-shaped traversal (containsSharedMemory): shared memory placed only
410	  // where cloning drops it (an attached property of a Date/RegExp, a
411	  // non-enumerable property, an Error own property other than cause) is
412	  // discarded with that property and never condemns the message.
413	  //
414	  // Validation only proves the message was safe as it was then; the same two
415	  // checks are re-enforced at the action's own execution moment by
416	  // captureActionMessage below, exactly as for end-node results.
417	  if (name === null && Object.hasOwn(node, 'message') && node.message !== undefined) {
418	    let cloned;
419	    try {
420	      cloned = structuredClone(node.message);
421	    } catch {
422	      throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
423	    }
424	    if (containsSharedMemory(cloned)) {
425	      throw new Error(ACTION_MESSAGE_SHARED_MEMORY_MESSAGE(node.id));
426	    }
427	  }
428	
429	  return { name, retry, compensation };
430	}
431	
432	// The two failure kinds a legacy message can produce, shared by definition
433	// validation (compileAction above) and the execution-time capture
434	// (captureActionMessage below): the message cannot be structured-cloned at
435	// all, or it clones but the clone retains shared memory. Uncloneability takes
436	// precedence when a message carries both, at both moments.
437	const ACTION_MESSAGE_UNCLONEABLE_MESSAGE = nodeId =>
438	  `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`;
439	const ACTION_MESSAGE_SHARED_MEMORY_MESSAGE = nodeId =>
440	  `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`;
441	
442	// Reads a legacy message action's configured message at the action's own
443	// execution moment and produces the independent copy that will be saved as
444	// the node's output. This re-enforces, for exactly the content this run is
445	// about to save, the promise validation already made for the message as it
446	// was then: an enumerable getter can return ordinary data during validation
447	// and shared memory (or a function) when the action later runs, and a
448	// preceding business operation — or work on another activated branch — can
449	// replace a message's plain buffer with a shared one before this action
450	// executes.
451	//
452	//   - the root message is read exactly once here, and every nested enumerable
453	//     accessor is read only by structuredClone's own read — there is no
454	//     separate inspection pass over the original, so a getter's return order
455	//     is never disturbed, and the value this read produced is both what is
456	//     judged and what is saved (a legal message whose getter answers with a
457	//     different ordinary value at execution time saves that fresh value);
458	//   - shared memory the clone retains is rejected (containsSharedMemory runs
459	//     on the clone), while shared memory placed only where cloning drops it
460	//     is discarded with that property and never condemns the message;
461	//   - uncloneability takes precedence over shared memory, matching
462	//     validation: the clone is attempted first and its failure short-circuits
463	//     before the shared-memory traversal. A root getter that throws, a nested
464	//     getter that throws while the clone reads it, and a value that cannot be
465	//     cloned at all (a function) all surface as the same uncloneable error.
466	//
467	// An unset, undefined or null message still defaults to action:<node id>,
468	// while "", 0 and false pass through untouched.
469	//
470	// Any failure is thrown here as an ordinary Error naming the action node
471	// rather than recorded as a run status: the synchronous entry propagates it
472	// and the asynchronous entry's rejected Promise carries it. It is never an
473	// action_failed — a legacy message action has no retry budget — and it
474	// neither consumes business-action retries nor triggers compensation, and no
475	// success output is recorded for the node.
476	function captureActionMessage(node) {
477	  let message;
478	  try {
479	    // The root value's single read: an absent, undefined or null message
480	    // takes the default; a root getter that throws is the uncloneable error.
481	    message = node.message;
482	  } catch {
483	    throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
484	  }
485	  if (message === undefined || message === null) return `action:${node.id}`;
486	  let cloned;
487	  try {
488	    cloned = structuredClone(message);
489	  } catch {
490	    throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
491	  }
492	  if (containsSharedMemory(cloned)) {
493	    throw new Error(ACTION_MESSAGE_SHARED_MEMORY_MESSAGE(node.id));
494	  }
495	  return cloned;
496	}
497	
498	// An end node's result is delivered to the caller verbatim for primitives
499	// (null, undefined, strings, numbers, booleans), but an object or array result
500	// must be structured-clonable. The independent-copy promise is enforced at
501	// BOTH moments it can be observed:
502	//
503	//  1. At validation time (compileEndResult below), for every end node in the
504	//     definition — including nodes on untaken branches and nodes the entry
505	//     cannot reach — so a statically invalid result is rejected before any
506	//     node can run.
507	//  2. At the end node's own execution moment (captureEndResult), against the
508	//     value actually about to be recorded: validation cannot see what an
509	//     enumerable getter returns on its later read, nor what a preceding
510	//     business operation or another activated branch does to the configured
511	//     result before this end runs. Only the content this run will save is
512	//     judged.
513	//
514	// The two failure kinds, in priority order: a value that cannot be
515	// structured-cloned (a bare function, a function nested in an object/array, a
516	// getter that throws, etc.), and a value that clones but whose clone retains
