1599	// The optional fourth argument of executeWorkflowAsync carries an
1600	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1601	// options object without a signal — keeps the previous behavior; anything
1602	// else is a caller error reported before a single node executes.
1603	function resolveRunSignal(options) {
