1614	export function executeWorkflow(workflow, input = {}) {
1615	  const nodes = validateWorkflow(workflow);
1616	  // Business operations are asynchronous: the synchronous entry must refuse
1617	  // a workflow that names any before a single node executes.
1618	  for (const node of nodes.values()) {
1619	    const binding = actionBindings.get(node);
1620	    if (binding && binding.name !== null) {
1621	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1622	    }
