1625	  const state = createRunState(nodes, workflow, input);
1626	
1627	  for (;;) {
1628	    const step = advanceSchedule(state);
1629	
1630	    if (step.kind === 'blocked') {
1631	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1632	    }
1633	    if (step.kind === 'completed') {
1634	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1635	    }
1636	    if (step.kind === 'end') continue;
1637	
1638	    const early = applyRegularNode(step.node, state);
1639	    if (early) return early;
