1643	// Attaches compensation results to a failed run. Successful outputs and the
1644	// original terminal status stay untouched; compensation records live on
1645	// their own fields, never in the regular node trace.
1646	async function withCompensation(result, state, operations) {
1647	  const outcome = await compensateRun(state, operations);
1648	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1649	  result.compensationAttempts = outcome.attempts;
1650	  return result;
1651	}
