1653	// The cancelled terminal shape: the run stops where it is, keeps the
1654	// context, trace and attempt records produced so far, and never carries a
1655	// success result. Compensation for already-succeeded actions is attached by
1656	// withCompensation under the usual rules.
1657	function cancelledResult(state) {
1658	  return {
1659	    status: 'cancelled',
1660	    context: state.context,
1661	    trace: state.trace,
1662	    actionAttempts: state.actionAttempts,
1663	  };
1664	}
1665	
1666	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1667	  const signal = resolveRunSignal(options);
1668	  const nodes = validateWorkflow(workflow);
1669	  verifyOperations(nodes, operations);
1670	
1671	  const state = createRunState(nodes, workflow, input);
1672	
1673	  // A signal that is already aborted stops the run before the first node —
1674	  // but only after the definition and the operation registrations above have
1675	  // been checked. Nothing executes and nothing is compensated.
1676	  if (signal && signal.aborted) {
1677	    return withCompensation(cancelledResult(state), state, operations);
1678	  }
1679	
1680	  for (;;) {
1681	    // Once the signal fires, no new regular node runs and no new business
1682	    // action attempt starts; the run ends cancelled with whatever state it
1683	    // reached, even if an end node was already visited on another branch.
1684	    if (signal && signal.aborted) {
1685	      return withCompensation(cancelledResult(state), state, operations);
1686	    }
