1692	      // rolled back even though an end node may already have been reached.
1693	      return withCompensation({
1694	        status: 'blocked', context: state.context, trace: state.trace,
1695	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1696	      }, state, operations);
1697	    }
